      "verbalModality": "paryupāsate — laṭ (present), 3rd pl., ātmanepada, kartari; pari + upa + √ās adādi 2A. The verb is stated once and governs both ye-clauses (Ānandagiri: anuṣaṅga); the English repeats it, slotted to the same word."
