    "grammar": {
      "karakaSummary": "Protasis (atha carried over from 12.9, Deśika): asi — copula with the unexpressed kartṛ tvam; asamarthaḥ — its predicate; abhyāse — the viṣaya-locative that samartha governs; api — 'even'. Apodosis: bhava — kartṛ tvam, predicate matkarmaparamaḥ (bahuvrīhi). Second sentence: avāpsyasi — kartṛ tvam; siddhim — karman; kurvan — present participle of the same agent, with karmāṇi as its karman and madartham as the purpose; api — 'even'.",
      "verbalModality": "asi — laṭ, 2 sg. of adādi √as, the copula of the supposed case (read conditionally by all commentators, with the atha of 12.9 understood). bhava — loṭ, 2 sg. of √bhū: the injunction. avāpsyasi — lṛṭ, 2 sg. of ava-√āp: the promise. kurvan — śatṛ: concurrent action of the agent. The English supplies 'If' for the atha carried over from 12.9. The two api's are concessive-emphatic ('even'): even the practice is beyond him; even mere action for his sake suffices."
    },
