    "grammar": {
      "karakaSummary": "Two clauses with one agent, the person addressed: (1) aśakto 'si kartum, 'you are unable to do', with etad as the object of the infinitive kartum (2.3.2); (2) kuru, with sarva-karma-phala-tyāgam as its object (2.3.2). The participle āśritaḥ, with mad-yogam as its own object, and the adjective yatātmavān describe that same agent; the Sanskrit does not fix whether āśritaḥ goes with asi or with kuru (see Other readings). atha opens the supposition and tataḥ answers it.",
      "verbalModality": "asi: present indicative (laṭ) stating the inability; kuru: imperative (loṭ) enjoining the relinquishment. atha with the indicative followed by tataḥ is the Sanskrit 'if … then' (Apte cites this verse and 12.9 for atha in the sense 'if'); there is no cet or yadi, and none is needed."
    },
